    /**
     * Method to retrieve the Room via an RoomPrimaryKey.
     * @param 	id Long
     * @return 	Room
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Room handle( FindRoomQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getRoomId() );
    }
    
    /**
     * Method to retrieve a collection of all Rooms
     *
     * @param	query	FindAllRoomQuery 
     * @return 	List<Room> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Room> handle( FindAllRoomQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindRoom,
 * but only if the id matches
 *
 * @param		entity	Room
 */
	protected void emitFindRoom( Room entity ) {
		LOGGER.info("handling emitFindRoom" );
		
	    queryUpdateEmitter.emit(FindRoomQuery.class,
	                            query -> query.getFilter().getRoomId().equals(entity.getRoomId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllRoom
	 * 
	 * @param		entity	Room
	 */
	protected void emitFindAllRoom( Room entity ) {
		LOGGER.info("handling emitFindAllRoom" );
		
	    queryUpdateEmitter.emit(FindAllRoomQuery.class,
	                            query -> true,
	                            entity);
	}

